export const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Kigali',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
export function seed(){return {version:1,settings:{name:'Twitezimbere',contribution:10000,frequency:'monthly',rate:2,term:6,goal:5000000},members:[{id:'m1',name:'Aline Uwase',phone:'0780 000 001',role:'treasurer'},{id:'m2',name:'Eric Mugisha',phone:'0780 000 002',role:'member'},{id:'m3',name:'Diane Ingabire',phone:'0780 000 003',role:'member'},{id:'m4',name:'Jean Niyonzima',phone:'0780 000 004',role:'chairperson'},{id:'m5',name:'Grace Mukamana',phone:'0780 000 005',role:'secretary'},{id:'m6',name:'Patrick Habimana',phone:'0780 000 006',role:'member'},{id:'m7',name:'Claudine Keza',phone:'0780 000 007',role:'member'},{id:'m8',name:'Samuel Ishimwe',phone:'0780 000 008',role:'member'}],payments:[{id:'p1',member:'m2',amount:10000,date:today(),method:'momo',purpose:'contribution',reference:'DEMO-1041',status:'pending',period:today().slice(0,7)},{id:'p2',member:'m3',amount:10000,date:today(),method:'cash',purpose:'contribution',reference:'',status:'pending',period:today().slice(0,7)},{id:'p3',member:'m6',amount:20000,date:today(),method:'bank',purpose:'contribution',reference:'DEMO-1043',status:'pending',period:today().slice(0,7)}],loans:[{id:'l1',member:'m2',amount:180000,purpose:'Business stock',term:6,rate:2,status:'active',disbursedAt:today(),paid:0},{id:'l2',member:'m3',amount:100000,purpose:'School fees',term:4,rate:2,status:'submitted',paid:0}],ledger:[{id:'opening',date:today(),kind:'opening',amount:2960000,member:null,detail:'Demo opening savings balance'},{id:'opening-loan',date:today(),kind:'disbursement',amount:180000,member:'m2',loan:'l1',detail:'Demo loan disbursement'}],audit:[]};}
export function money(n){if(!Number.isSafeInteger(n)||n<=0||n>1000000000)throw Error('invalidAmount');return n;}
export function loanSchedule(l){
 const bps=Math.round(l.rate*100),round=(n)=>Number((BigInt(n)*BigInt(bps)+5000n)/10000n),part=Math.floor(l.amount/l.term),flatTotal=Number((BigInt(l.amount)*BigInt(bps)*BigInt(l.term)+5000n)/10000n);
 let remaining=l.amount,paid=l.paid||0;const schedule=[];
 for(let i=0;i<l.term;i++){const principal=i===l.term-1?remaining:part;const interest=l.interestMethod==='reducing'?round(remaining):(i===l.term-1?flatTotal-Math.floor(flatTotal/l.term)*(l.term-1):Math.floor(flatTotal/l.term));const interestPaid=Math.min(paid,interest);paid-=interestPaid;const principalPaid=Math.min(paid,principal);paid-=principalPaid;let dueDate=null;if(l.disbursedAt){const start=new Date(l.disbursedAt+'T12:00:00Z'),year=start.getUTCFullYear(),month=start.getUTCMonth()+i+1,day=start.getUTCDate(),last=new Date(Date.UTC(year,month+1,0)).getUTCDate();dueDate=new Date(Date.UTC(year,month,Math.min(day,last),12)).toISOString().slice(0,10);}schedule.push({number:i+1,dueDate,principal,interest,total:principal+interest,principalPaid,interestPaid,outstanding:principal+interest-principalPaid-interestPaid});remaining-=principal;}
 return schedule;
}
export function loanTotals(l){const schedule=loanSchedule(l),interest=schedule.reduce((n,e)=>n+e.interest,0),principalPaid=schedule.reduce((n,e)=>n+e.principalPaid,0),interestPaid=schedule.reduce((n,e)=>n+e.interestPaid,0);return {principal:l.amount,interest,total:l.amount+interest,outstanding:l.amount+interest-(l.paid||0),principalPaid,interestPaid,principalOutstanding:l.amount-principalPaid};}
export function totals(s){let contributions=0,out=0,repayments=0,expenses=0,withdrawals=0;for(const e of s.ledger){const kind=e.kind==='reversal'?e.originalKind:e.kind,sign=e.kind==='reversal'?-1:1;if(['contribution','opening'].includes(kind))contributions+=sign*e.amount;if(kind==='disbursement')out+=sign*e.amount;if(kind==='repayment')repayments+=sign*e.amount;if(kind==='expense')expenses+=sign*e.amount;if(kind==='withdrawal')withdrawals+=sign*e.amount;}return {savings:contributions-withdrawals,contributions,withdrawals,expenses,cash:contributions-out+repayments-expenses-withdrawals,loans:s.loans.filter(l=>l.status==='active').reduce((n,l)=>n+loanTotals(l).outstanding,0),pending:s.payments.filter(p=>p.status==='pending').length};}
export function audit(s,actor,action,detail){s.audit.unshift({id:crypto.randomUUID(),date:new Date().toISOString(),actor,action,detail});}
export function submitPayment(s,actor,data){if(!s.members.some(m=>m.id===actor))throw Error('forbidden');money(data.amount);if(!/^\d{4}-\d{2}-\d{2}$/.test(data.date)||data.date>today())throw Error('invalidDate');if(!['cash','momo','bank'].includes(data.method)||!['contribution','repayment'].includes(data.purpose))throw Error('invalidAmount');if(data.purpose==='repayment'){const l=s.loans.find(l=>l.id===data.loan&&l.member===actor&&l.status==='active');if(!l||data.amount>loanTotals(l).outstanding)throw Error('invalidLoan');}else if(!/^\d{4}-\d{2}$/.test(data.period||''))throw Error('invalidDate');const ref=(data.reference||'').trim();if(ref&&s.payments.some(p=>p.reference?.toLowerCase()===ref.toLowerCase()&&p.status!=='rejected'))throw Error('duplicate');const p={...data,reference:ref,id:crypto.randomUUID(),member:actor,status:'pending',submittedAt:new Date().toISOString()};s.payments.unshift(p);audit(s,actor,'submitted',p.id);return p;}
export function reviewPayment(s,actor,id,decision,reason=''){if(s.members.find(m=>m.id===actor)?.role!=='treasurer')throw Error('forbidden');const p=s.payments.find(p=>p.id===id);if(!p||p.status!=='pending')throw Error('alreadyReviewed');if(!['approved','rejected'].includes(decision))throw Error('invalidAmount');if(decision==='rejected'&&!reason.trim())throw Error('reasonRequired');if(decision==='approved'){if(p.purpose==='repayment'){const l=s.loans.find(l=>l.id===p.loan&&l.member===p.member&&l.status==='active');if(!l||p.amount>loanTotals(l).outstanding)throw Error('invalidLoan');l.paid=(l.paid||0)+p.amount;if(loanTotals(l).outstanding===0)l.status='repaid';}s.ledger.unshift({id:crypto.randomUUID(),date:today(),kind:p.purpose==='repayment'?'repayment':'contribution',amount:p.amount,member:p.member,payment:p.id,loan:p.loan||null,detail:p.reference});}p.status=decision;p.reviewedBy=actor;p.reviewedAt=new Date().toISOString();p.reason=reason.trim();audit(s,actor,decision,p.id);}
export function requestLoan(s,actor,data){if(!s.members.some(m=>m.id===actor))throw Error('forbidden');money(data.amount);if(!Number.isInteger(data.term)||data.term<1||data.term>s.settings.term)throw Error('invalidTerm');if(!data.purpose.trim())throw Error('reasonRequired');s.loans.unshift({...data,id:crypto.randomUUID(),member:actor,rate:s.settings.rate,interestMethod:s.settings.interestMethod||'flat',status:'submitted',paid:0,createdAt:new Date().toISOString()});audit(s,actor,'loanRequested',String(data.amount));}
export function reviewLoan(s,actor,id,decision,reason=''){if(s.members.find(m=>m.id===actor)?.role!=='chairperson')throw Error('forbidden');const l=s.loans.find(l=>l.id===id);if(!l||l.status!=='submitted')throw Error('alreadyReviewed');if(!['approved','rejected'].includes(decision))throw Error('invalidAmount');if(decision==='rejected'&&!reason.trim())throw Error('reasonRequired');l.status=decision;l.reviewedBy=actor;l.reviewedAt=new Date().toISOString();l.reason=reason;audit(s,actor,decision,id);}
export function disburse(s,actor,id,reference,disbursementDate=today()){if(s.members.find(m=>m.id===actor)?.role!=='treasurer')throw Error('forbidden');const l=s.loans.find(l=>l.id===id);if(!l||l.status!=='approved')throw Error('alreadyReviewed');if(!reference.trim())throw Error('reasonRequired');if(l.amount>totals(s).cash)throw Error('insufficient');l.status='active';l.disbursedAt=disbursementDate;s.ledger.unshift({id:crypto.randomUUID(),date:today(),kind:'disbursement',amount:l.amount,member:l.member,loan:l.id,detail:reference});audit(s,actor,'disbursed',id);}
